  const contCaps = document.getElementById('capitulos');
  if (contCaps) {
    CATEGORIAS.forEach(cat => {
      const sec = document.createElement('section');
      sec.className = 'cat';
      sec.id = 'cat-' + cat.id;

      let cuerpo;
      if (cat.items.length) {
        // duplicamos la lista para loop continuo sin salto
        const uno = cat.items.map(it =>
          '<figure class="' + (it.orient === 'v' ? 'vert' : '') + '">' +
            '<img src="' + it.src + '" alt="' + cat.nombre + '" loading="lazy">' +
            '<figcaption>' + it.cap + '</figcaption>' +
          '</figure>').join('');
        cuerpo = '<div class="cinta-wrap"><div class="cinta">' + uno + uno + '</div></div>';
      } else {
        cuerpo = '<div class="cat-vacia">Galería en preparación</div>';
      }

      sec.innerHTML =
        '<div class="cat-head">' +
          '<span class="nom">' + cat.nombre + '</span>' +
          '<div class="meta">' +
            '<span class="det">' + cat.det + '</span>' +
            '<a class="cta" href="' + cat.cta + '" target="_blank" rel="noopener">COTIZAR →</a>' +
          '</div>' +
        '</div>' + cuerpo;
      contCaps.appendChild(sec);
    });

    // --- Motor de cinta: auto-desplazamiento continuo + arrastre ---
    const prefiereQuieto = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    contCaps.querySelectorAll('.cinta-wrap').forEach(wrap => {
      const cinta = wrap.querySelector('.cinta');
      let x = 0;                 // desplazamiento actual (px, negativo)
      let mitad = 0;             // ancho de una vuelta (la lista sin duplicar)
      const velocidad = 0.4;     // px por frame (~24px/s a 60fps)
      let auto = !prefiereQuieto;
      let visible = true;

      const recalcular = () => { mitad = cinta.scrollWidth / 2; };
      recalcular();
      window.addEventListener('resize', recalcular);
      window.addEventListener('load', recalcular);

      // pausa cuando la sección no está en pantalla (rendimiento)
      const io = new IntersectionObserver(es => { visible = es[0].isIntersecting; },
        { threshold: 0 });
      io.observe(wrap);

      // reveal de apertura: la cinta se despliega al entrar en pantalla
      if (prefiereQuieto) {
        wrap.classList.add('abierta');
      } else {
        const ioReveal = new IntersectionObserver(es => {
          if (es[0].isIntersecting) { wrap.classList.add('abierta'); ioReveal.disconnect(); }
        }, { threshold: 0.25 });
        ioReveal.observe(wrap);
        setTimeout(() => wrap.classList.add('abierta'), 1600); // respaldo
      }

      // pausa al pasar el mouse (desktop)
      wrap.addEventListener('mouseenter', () => { auto = false; });
      wrap.addEventListener('mouseleave', () => { if (!arrastre.activo && !prefiereQuieto) auto = true; });

      const normalizar = () => {
        if (mitad <= 0) return;
        if (x <= -mitad) x += mitad;   // volvió una vuelta entera → reset invisible
        if (x > 0) x -= mitad;
      };

      const tick = () => {
        if (auto && visible && !arrastre.activo) {
          x -= velocidad;
          normalizar();
          cinta.style.transform = 'translateX(' + x + 'px)';
        }
        requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);

      // --- Arrastre / swipe ---
      const arrastre = { activo:false, startX:0, startPos:0, movido:false, reanudar:null };

      const onDown = e => {
        arrastre.activo = true; arrastre.movido = false;
        arrastre.startX = (e.touches ? e.touches[0].clientX : e.clientX);
        arrastre.startPos = x;
        wrap.classList.add('arrastrando');
        auto = false;
        if (arrastre.reanudar) clearTimeout(arrastre.reanudar);
      };
      const onMove = e => {
        if (!arrastre.activo) return;
        const cx = (e.touches ? e.touches[0].clientX : e.clientX);
        const d = cx - arrastre.startX;
        if (Math.abs(d) > 4) arrastre.movido = true;
        x = arrastre.startPos + d;
        normalizar();
        cinta.style.transform = 'translateX(' + x + 'px)';
      };
      const onUp = () => {
        if (!arrastre.activo) return;
        arrastre.activo = false;
        wrap.classList.remove('arrastrando');
        // retoma solo tras un ratito
        if (!prefiereQuieto) arrastre.reanudar = setTimeout(() => { auto = true; }, 1200);
      };

      wrap.addEventListener('mousedown', onDown);
      window.addEventListener('mousemove', onMove);
      window.addEventListener('mouseup', onUp);
      wrap.addEventListener('touchstart', onDown, { passive:true });
      wrap.addEventListener('touchmove', onMove, { passive:true });
      wrap.addEventListener('touchend', onUp);

      // evitar que un arrastre dispare el click en el caption/imagen
      wrap.addEventListener('click', e => { if (arrastre.movido) { e.preventDefault(); e.stopPropagation(); } }, true);
    });
  }

